import{_ as s,a0 as p,w as i,s as r,I as l,x as t,a1 as n,A as o,ao as m}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"在Ubuntu14.10/Mint7上安裝Gnome Flashback  經典桌面 | LCTT x X-CMD","titleTemplate":false,"description":"在Ubuntu14.10/Mint7上安裝Gnome Flashback  經典桌面 | LCTT (201504) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在Ubuntu14.10/Mint7上安裝Gnome Flashback  經典桌面 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在Ubuntu14.10/Mint7上安裝Gnome Flashback  經典桌面 | LCTT (201504) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201504/20150209 Install the Gnome Flashback classical desktop on Ubuntu 14.10 or Linux Mint 17","title":"在Ubuntu14.10/Mint7上安裝Gnome Flashback  經典桌面","tag":"201504","desc":""},"relativePath":"201504/20150209 Install the Gnome Flashback classical desktop on Ubuntu 14.10 or Linux Mint 17.md","filePath":"[post].md"}'),u={name:"201504/20150209 Install the Gnome Flashback classical desktop on Ubuntu 14.10 or Linux Mint 17.md"};function d(k,a,b,c,h,g){const e=p("Link");return i(),r("div",null,[a[16]||(a[16]=l("h1",{id:"在ubuntu14-10-mint7上安裝gnome-flashback-經典桌面",tabindex:"-1"},[t("在Ubuntu14.10/Mint7上安裝Gnome Flashback 經典桌面 "),l("a",{class:"header-anchor",href:"#在ubuntu14-10-mint7上安裝gnome-flashback-經典桌面","aria-label":"Permalink to “在Ubuntu14.10/Mint7上安裝Gnome Flashback  經典桌面”"},"​")],-1)),l("p",null,[a[1]||(a[1]=t("如果你不喜歡現在的Unity桌面，",-1)),n(e,{href:"https://wiki.gnome.org/action/show/Projects/GnomeFlashback?action=show&redirect=GnomeFlashback"},{default:o(()=>[...a[0]||(a[0]=[t("Gnome Flashback",-1)])]),_:1}),a[2]||(a[2]=t("桌面環境是一個簡單的並且很棒的選擇，讓你能找回曾經經典的桌面。",-1))]),a[17]||(a[17]=m(`<p>Gnome Flashback基於GTK3並提供與原先gnome桌面視覺上相似的界面。</p><p>Gnome Flashback的另一個改變是採用了源自mint和xface的MATE桌面，但無論mint還是xface都是基於GTK2的。</p><h3 id="安裝-gnome-flashback" tabindex="-1">安裝 Gnome Flashback <a class="header-anchor" href="#安裝-gnome-flashback" aria-label="Permalink to “安裝 Gnome Flashback”">​</a></h3><p>在你的ubuntu上安裝以下包即可：</p><pre><code>$ sudo apt-get install gnome-session-flashback
</code></pre><p>然後註銷返回到登錄界面，單擊密碼輸入框右上角的徽標型按鈕，即可選擇桌面環境。可供選擇的有Gnome Flashback (Metacity) 會話模式和Gnome Flashback (Compiz)會話模式。</p><p>Metacity更輕更快，而Compiz則能帶給你更棒的桌面效果。下面是我使用gnome flashback桌面的截圖。</p><p>桌面採用了elementary OS的壁紙和Plank dock並且移除了底部面板。這些都會在這篇教程中涉及到。</p><p><img src="http://www.binarytides.com/blog/wp-content/uploads/2015/02/ubuntu-gnome-flashback.png" alt="ubuntu gnome flashback"></p><p>在安裝好gnome flashback桌面以後也許你對效果還不滿意，這樣你可能需要執行接下來的一系列操作來對它進行微調。</p><h3 id="_1-安裝-gnome-tweak-tool" tabindex="-1">1. 安裝 Gnome Tweak Tool <a class="header-anchor" href="#_1-安裝-gnome-tweak-tool" aria-label="Permalink to “1. 安裝 Gnome Tweak Tool”">​</a></h3><p>Gnome Tweak Tool能夠幫助你定製比如字體、主題等，這些在Unity桌面的控制中心是十分困難，幾乎不可能完成的任務。</p><pre><code>$ sudo apt-get install gnome-tweak-tool
</code></pre><p>啓動按步驟： 應用程序 &gt; 系統工具 &gt; 首選項 &gt; Tweak Tool</p><h3 id="_2-在面板上添加小應用" tabindex="-1">2. 在面板上添加小應用 <a class="header-anchor" href="#_2-在面板上添加小應用" aria-label="Permalink to “2. 在面板上添加小應用”">​</a></h3><p>默認的右鍵點擊面板是沒有效果的。你可以嘗試在右鍵點擊面板的同時按住鍵盤上的Alt+Super (win)鍵，這樣就會出現定製面板的相關選項。</p><p>你可以修改或刪除面板，並在上面添加些小應用。在這個例子中我們移除了底部面板，並用Plank dock來代替它的位置。</p><p>在頂部面板的中間添加一個顯示時間的小應用。通過配置使它顯示時間和天氣。</p><p>同樣的添加一個工作空間切換器到頂部面板，並創建合適個數的工作空間。</p><h3 id="_3-將窗口標題欄的按鈕右置" tabindex="-1">3. 將窗口標題欄的按鈕右置 <a class="header-anchor" href="#_3-將窗口標題欄的按鈕右置" aria-label="Permalink to “3. 將窗口標題欄的按鈕右置”">​</a></h3><p>在ubuntu中，最小化、最大化和關閉按鈕默認是在標題欄左側的。需要稍作手腳才能讓他們乖乖回到右邊去。</p><p>想讓窗口的按鈕到右邊可以使用下面的命令，這是我在askubuntu上找到的。</p><pre><code>$ gsettings set org.gnome.desktop.wm.preferences button-layout &#39;menu:minimize,maximize,close&#39;
</code></pre><h3 id="_4-安裝-plank-dock" tabindex="-1">4.安裝 Plank dock <a class="header-anchor" href="#_4-安裝-plank-dock" aria-label="Permalink to “4.安裝 Plank dock”">​</a></h3><p>plank dock位於屏幕底部，用於啓動應用和切換打開的窗口。它會在必要的時間隱藏自己，並在需要的時候出現。elementary OS使用的dock就是plank dock。</p><p>運行以下命令安裝:</p><pre><code>$ sudo add-apt-repository ppa:ricotz/docky -y 
$ sudo apt-get update 
$ sudo apt-get install plank -y
</code></pre><p>現在啓動：應用程序 &gt; 附件 &gt; Plank。若想讓它開機自動啓動，找到 應用程序 &gt; 系統工具 &gt; 首選項 &gt; 啓動應用程序 並將“plank”的命令加到列表中。</p><h3 id="_5-安裝-conky-系統監視器" tabindex="-1">5. 安裝 Conky 系統監視器 <a class="header-anchor" href="#_5-安裝-conky-系統監視器" aria-label="Permalink to “5. 安裝 Conky 系統監視器”">​</a></h3><p>Conky非常酷，它用系統的中如CPU和內存使用率的統計值來裝飾桌面。它不太佔資源，並且絕大部分情況下運行都不會有什麼問題。</p><p>運行如下命令安裝:</p><pre><code>$ sudo apt-add-repository -y ppa:teejee2008/ppa
$ sudo apt-get update
$ sudo apt-get install conky-manager
</code></pre><p>現在啓動：應用程序 &gt; 附件 &gt; Conky Manager ，選擇你想在桌面上顯示的部件。Conky Manager同樣可以配置到啓動項中。</p><h3 id="_6-安裝ccsm" tabindex="-1">6. 安裝CCSM <a class="header-anchor" href="#_6-安裝ccsm" aria-label="Permalink to “6. 安裝CCSM”">​</a></h3><p>如果你更願意使用Gnome Flashback (Compiz)，那麼CCSM將是你配置桌面特效的得力助手。</p><p>運行以下命令安裝:</p><pre><code>$ sudo apt-get install compizconfig-settings-manager
</code></pre><p>啓動按步驟： 應用程序 &gt; 系統工具 &gt; 首選項 &gt; CompizConfig Settings Manager.</p><blockquote><p>在虛擬機中經常會發生compiz會話中裝飾窗口消失。可以通過啓動Compiz設置，並啓用&quot;Copy to texture&quot;插件，註銷後重新登錄即可。</p></blockquote><p>不過值得一提的是Compiz 會話會比Metacity慢。</p><hr>`,41)),l("p",null,[a[4]||(a[4]=t("via: ",-1)),n(e,{href:"http://www.binarytides.com/install-gnome-flashback-ubuntu/"},{default:o(()=>[...a[3]||(a[3]=[t("http://www.binarytides.com/install-gnome-flashback-ubuntu/",-1)])]),_:1})]),l("p",null,[a[8]||(a[8]=t("作者：",-1)),n(e,{href:"https://plus.google.com/117145272367995638274/posts"},{default:o(()=>[...a[5]||(a[5]=[t("Silver Moon",-1)])]),_:1}),a[9]||(a[9]=t(" 譯者：",-1)),n(e,{href:"https://github.com/martin2011qi"},{default:o(()=>[...a[6]||(a[6]=[t("martin2011qi",-1)])]),_:1}),a[10]||(a[10]=t(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:o(()=>[...a[7]||(a[7]=[t("wxy",-1)])]),_:1})]),l("p",null,[a[13]||(a[13]=t("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...a[11]||(a[11]=[t("LCTT",-1)])]),_:1}),a[14]||(a[14]=t(" 原創翻譯，",-1)),n(e,{href:"http://linux.cn/"},{default:o(()=>[...a[12]||(a[12]=[t("Linux中國",-1)])]),_:1}),a[15]||(a[15]=t(" 榮譽推出",-1))])])}const x=s(u,[["render",d]]);export{T as __pageData,x as default};
